static bool Admit(){
 HMODULE module=GetModuleHandleA("OgreMain_x64.dll");DWORD stamp=0,size=0;
 __try{return IsMainThread()&&ReadModuleImageId(module,&stamp,&size)&&stamp==0x5ca5f929&&size==0x9c9000&&memcmp((char*)module+0x1a9be0,nativeProof,sizeof(nativeProof))==0;}
 __except(EXCEPTION_EXECUTE_HANDLER){return false;}
}
void Init(){
 admitted=Admit();
 if(!admitted)LogError("Parallel body math: native pose contract refused; native calculations retained");
 else{
  if(fixes::g_fixesCfg.morphParallelEnabled&&!pose_cpu_pool::Prepare())LogError("Parallel body math: helper pool preparation failed; native fallback available");
  KEO_DETAIL("Parallel body math: immediate CPU-only dense pose accelerator admitted");
 }
}
